-- Options snapshot for first installation. Generated by npm run options:dump.

-- Contains only options; no presets, settings, or local paths.

BEGIN TRANSACTION;

CREATE TABLE options (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  comment TEXT NOT NULL CHECK (length(trim(comment)) > 0),
  category TEXT NOT NULL CHECK (category IN ('world', 'items', 'challenge', 'relics', 'gameplay')),
  type TEXT NOT NULL CHECK (type IN ('char', 'short', 'word', 'long', 'string')),
  value TEXT NOT NULL CHECK (length(trim(value)) > 0),
  address TEXT CHECK (address IS NULL OR length(trim(address)) > 0),
  game_init INTEGER NOT NULL DEFAULT 0 CHECK (game_init IN (0, 1)),
  raw_json INTEGER NOT NULL DEFAULT 0 CHECK (raw_json IN (0, 1)),
  additional_writes_json TEXT CHECK (
    additional_writes_json IS NULL OR
    (json_valid(additional_writes_json) AND json_type(additional_writes_json) = 'array')
  ),
  created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
, stat_edit INTEGER NOT NULL DEFAULT 0 CHECK (stat_edit IN (0, 1)), description TEXT NOT NULL DEFAULT '', read_only INTEGER NOT NULL DEFAULT 0 CHECK (read_only IN (0, 1)), primary_write_json TEXT CHECK (primary_write_json IS NULL OR (json_valid(primary_write_json) AND json_type(primary_write_json) = 'object')), writes_json TEXT CHECK (writes_json IS NULL OR (json_valid(writes_json) AND json_type(writes_json) = 'array')), item_init INTEGER NOT NULL DEFAULT 0 CHECK (item_init IN (0, 1)));

INSERT INTO "options" ("id", "comment", "category", "type", "value", "address", "game_init", "raw_json", "additional_writes_json", "created_at", "updated_at", "stat_edit", "description", "read_only", "primary_write_json", "writes_json", "item_init") VALUES (1, 'Enable Soul of Bat', 'relics', 'word', '0xa0627964', NULL, 0, 0, NULL, '2026-09-04 16:49:24', '2026-09-04 17:01:32', 0, '', 1, NULL, '[{"comment":"Enable Soul of Bat","type":"word","value":"0xa0627964"}]', 0);

